-- -----------------------------------
-- Table structure for `loginusers`
-- -----------------------------------

DROP TABLE IF EXISTS `loginusers`;
CREATE TABLE `loginusers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8 NOT NULL,
  `uname` varchar(100) CHARACTER SET utf8 NOT NULL,
  `pwd` varchar(150) CHARACTER SET utf8 NOT NULL,
  `permission` varchar(200) CHARACTER SET utf8 NOT NULL,
  `designation` varchar(200) CHARACTER SET utf8 NOT NULL,
  `level` varchar(191) CHARACTER SET utf8 NOT NULL,
  `cust_id` text CHARACTER SET utf8 NOT NULL,
  `bank_id` text CHARACTER SET utf8 NOT NULL,
  `currentstatus` int(11) NOT NULL DEFAULT '0' COMMENT '0-logout,1-login',
  `alerts` int(11) NOT NULL DEFAULT '0',
  `branch` varchar(200) CHARACTER SET utf8 NOT NULL,
  `zone` varchar(200) CHARACTER SET utf8 NOT NULL,
  `mac_id` text CHARACTER SET utf8,
  `zonal` text CHARACTER SET utf8,
  `circle_id` text CHARACTER SET utf8,
  `is_change_pwd` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uname` (`uname`),
  KEY `id` (`id`),
  KEY `designation` (`designation`)
) ENGINE=MyISAM AUTO_INCREMENT=934 DEFAULT CHARSET=latin1;

